import { buildTheme } from "./derive";
import { contrastFailures } from "./repair";
import { importVscodeTheme, stripJsonc, ThemeImportError } from "./vscode";

// Shaped like One Dark Pro's own file: comments, trailing commas, alpha colors.
const ONE_DARK_LIKE = `{
  // Generated by the extension's build
  "name": "One Dark Pro",
  "type": "dark",
  "semanticHighlighting": true,
  "colors": {
    "editor.background": "#282c34",
    "editor.foreground": "#abb2bf",
    "sideBar.background": "#21252b",
    "editorWidget.background": "#21252b",
    "dropdown.background": "#21252b",
    "descriptionForeground": "#abb2bf80", /* half-transparent */
    "panel.border": "#3e4452",
    "textLink.foreground": "#61afef",
    "focusBorder": "#3e4452",
    "button.background": "#404754",
    "button.foreground": "#ffffff",
    "gitDecoration.addedResourceForeground": "#81b88b",
    "errorForeground": "#c24038",
    "editorError.foreground": "#c24038",
    "editorWarning.foreground": "#cca700",
    "editorInfo.foreground": "#2f80ed",
    "diffEditor.insertedTextBackground": "#00809b33",
    "terminal.ansiGreen": "#8cc265",
  },
  "tokenColors": [
    { "name": "Comment", "scope": ["comment", "punctuation.definition.comment"], "settings": { "foreground": "#7f848e", "fontStyle": "italic" } },
    { "scope": "keyword.operator", "settings": { "foreground": "#56b6c2" } },
    { "scope": ["keyword.control", "storage.type"], "settings": { "foreground": "#c678dd" } },
    { "scope": "string, string.quoted.double", "settings": { "foreground": "#98c379" } },
    { "scope": "constant.numeric", "settings": { "foreground": "#d19a66" } },
    { "scope": ["entity.name.function", "support.function"], "settings": { "foreground": "#61afef" } },
    { "scope": "entity.name.type.class", "settings": { "foreground": "#e5c07b" } },
    { "scope": "source.js keyword", "settings": { "foreground": "#ff0000" } },
  ],
}`;

describe("importVscodeTheme", () => {
  it("reads a One Dark Pro-like theme into a seed", () => {
    const theme = importVscodeTheme(ONE_DARK_LIKE);
    expect(theme.name).toBe("One Dark Pro");
    expect(theme.base).toBe("dark");
    expect(theme.seed).toMatchObject({
      bg: "#282C34",
      ink: "#ABB2BF",
      panel: "#21252B",
      panel2: "#21252B",
      line: "#3E4452",
      accent: "#61AFEF",
      action: "#404754",
      success: "#81B88B",
      danger: "#C24038",
      warning: "#CCA700",
      info: "#2F80ED",
      // Not the operator color: the control keywords'.
      keyword: "#C678DD",
      string: "#98C379",
      number: "#D19A66",
      function: "#61AFEF",
      type: "#E5C07B",
      comment: "#7F848E",
    });
    // Alpha is painted over the editor's background.
    expect(theme.seed.muted).toBe("#6A6F7A");
    expect(theme.seed.diffAddBg).toMatch(/^#[0-9A-F]{6}$/);
  });

  it("makes a theme that reads well once repaired", () => {
    const { seed, base } = importVscodeTheme(ONE_DARK_LIKE);
    const { tokens, fixes } = buildTheme(seed, base);
    expect(contrastFailures(tokens)).toEqual([]);
    // Its red error text was too dark for AA on these surfaces.
    expect(fixes.some((f) => f.token === "danger")).toBe(true);
  });

  it("tells light from dark by `type`, or by the background without one", () => {
    const light = `{"type": "light", "colors": {"editor.background": "#ffffff", "editor.foreground": "#333333"}}`;
    expect(importVscodeTheme(light).base).toBe("light");
    const hc = `{"type": "hcLight", "colors": {"editor.background": "#ffffff", "editor.foreground": "#000000"}}`;
    expect(importVscodeTheme(hc).base).toBe("light");
    const untyped = `{"colors": {"editor.background": "#fafafa", "foreground": "#222"}}`;
    expect(importVscodeTheme(untyped)).toMatchObject({ base: "light", name: null, seed: { ink: "#222222" } });
  });

  it.each([
    ["not json at all", "invalidJson"],
    ["[1, 2]", "notTheme"],
    [`{"name": "x"}`, "notTheme"],
    [`{"include": "./base.json", "tokenColors": []}`, "include"],
    [`{"colors": {"editor.foreground": "#fff"}}`, "missingColors"],
  ])("rejects %s (%s)", (text, code) => {
    expect(() => importVscodeTheme(text)).toThrow(ThemeImportError);
    try {
      importVscodeTheme(text);
    } catch (error) {
      expect((error as ThemeImportError).code).toBe(code);
    }
  });
});

describe("stripJsonc", () => {
  it("keeps comment-like text inside strings", () => {
    expect(JSON.parse(stripJsonc(`{"url": "https://x.dev/*a*/", // note\n "b": [1,2,],}`))).toEqual({
      url: "https://x.dev/*a*/",
      b: [1, 2],
    });
  });
});
